import pandas as pd
import numpy as np
import math

def engineer_features(df):
    """
    Transform raw flat features into model-ready features, focusing on 
    the relationship between aggressive flow (Delta) and liquidity 
    positioning (OBI) to identify trend vs. absorption regimes.
    """
    df = df.copy()

    # 1. OBI Agreement: Measure of consensus across exchanges (0 to 1)
    df['obi_agreement'] = 1.0 - (df['obi_spread'] / 2.0)

    # 2. Delta-OBI Congruence: 
    #  1.0: Trend (Delta and OBI have same sign)
    # -1.0: Absorption (Delta and OBI have opposite signs)
    #  0.0: Neutral/No signal
    df['delta_obi_congruence'] = np.sign(df['mean_delta']) * np.sign(df['mean_obi'])

    # 3. Volatility-Normalized Delta: Aggressive flow relative to current volatility
    # We clip to prevent extreme outliers from destabilizing the model.
    df['delta_norm'] = (df['mean_delta'] / (df['mean_volatility'] + 1e-6)).clip(-10, 10)

    # Drop metadata and target
    # We also drop seconds_remaining as it is passed separately to the filter
    cols_to_drop = ['market_slug', 'timestamp', 'actual_outcome', 'seconds_remaining']
    X = df.drop(columns=[c for c in cols_to_drop if c in df.columns])

    # Final cleanup
    X = X.replace([np.inf, -np.inf], 0)
    X = X.fillna(0)

    return X

def get_hyperparams():
    """Return regularized hyperparameters to capture regime-based signals."""
    return {
        'n_estimators': 1000,
        'max_depth': 2,
        'learning_rate': 0.01,
        'subsample': 0.6,
        'colsample_bytree': 0.6,
        'reg_alpha': 15.0,
        'reg_lambda': 15.0,
    }

def strategy_filter(prob_up, prob_down, cost_up, cost_down, features_row, seconds_remaining):
    """
    Decide whether to trade using "Congruence-Based Regime Switching (CBRS)".

    Logic:
    1. Identify the best Expected Value (EV) side.
    2. Determine the Microstructure Regime:
       - Trend Regime (Congruence > 0): Delta and OBI are aligned.
       - Absorption Regime (Congruence < 0): Delta and OBI are diverging.
    3. Apply Regime-Specific Multipliers:
       - In Trends: Scale bet by OBI agreement. Only take counter-trend trades with heavy penalty.
       - In Absorption: Scale bet by (1 - OBI agreement). Only take "fighting absorption" trades with heavy penalty.
    """
    # 1. Calculate Expected Value (EV)
    ev_up = prob_up - cost_up
    ev_down = prob_down - cost_down

    if ev_up > ev_down:
        best_ev = ev_up
        side = 'Up'
    else:
        best_ev = ev_down
        side = 'Down'

    # 2. Time-gate: Avoid the final 30 seconds of noise
    if seconds_remaining < 30:
        return None, 0.0

    # 3. Minimum Edge Threshold
    if best_ev < 0.025:
        return None, 0.0

    # 4. Extract Microstructure State
    congruence = features_row.get('delta_obi_congruence', 0)
    agreement = features_row.get('obi_agreement', 0.5)
    
    # Determine the sign of the aggressive flow
    mean_delta = features_row.get('mean_delta', 0)
    delta_sign = 1 if mean_delta > 0 else (-1 if mean_delta < 0 else 0)

    multiplier = 0.5 # Default neutral multiplier

    # 5. Regime-Conditional Logic
    if congruence > 0:
        # TREND REGIME: We want to follow the delta
        if (delta_sign > 0 and side == 'Up') or (delta_sign < 0 and side == 'Down'):
            multiplier = agreement
        else:
            # Counter-trend trade: High risk of hitting a wall
            multiplier = (1.0 - agreement) * 0.3
            
    elif congruence < 0:
        # ABSORPTION REGIME: We want to trade against the delta (reversal)
        if (delta_sign > 0 and side == 'Down') or (delta_sign < 0 and side == 'Up'):
            multiplier = (1.0 - agreement)
        else:
            # Fighting absorption: High risk of being run over
            multiplier = agreement * 0.3
    else:
        # Neutral/No flow: Moderate confidence
        multiplier = 0.5

    # 6. Dynamic Bet Sizing
    # Scale bet_fraction linearly with EV, normalized by a 3% target edge.
    bet_fraction = (best_ev / 0.03) * multiplier

    # Clamp bet_fraction to [0.0, 1.0]
    bet_fraction = max(0.0, min(1.0, bet_fraction))

    if bet_fraction > 0:
        return side, bet_fraction

    return None, 0.0